// 1. OBTENEMOS LOS CURSOS QUE CUMPLEN LOS FILTROS
ClearCollect(
    colCursosFiltrados,
    Filter(
        'Cursos Formativos',
        (IsBlank(ComboBox_Area.Selected) || Area_Form = ComboBox_Area.Selected.Value),
        (IsBlank(Plan_Formativo.Selected) || Plan_Form = Plan_Formativo.Selected.Value)
    )
);

ClearCollect(
    colEmpleadosBase,
    Distinct(
        Filter(
            'Listado enviado a 04 Octubre', 
            (IsBlank(ComboBox_Equipo.Selected.Value) || Tipo_Empleo = ComboBox_Equipo.Selected.Value),
            
            (IsBlank(ComboBox_N_Empleado.Selected.N_Empleado) || N_Empleado = Value(ComboBox_N_Empleado.Selected.N_Empleado))
        ),
        N_Empleado
    )
);

// 3. DESCARGAMOS EL HISTORIAL DE FORMACIÓN DE ESOS EMPLEADOS ESPECÍFICOS
Clear(colRegistrosTemp);
ForAll(
    colEmpleadosBase As Emp,
    Collect(
        colRegistrosTemp,
        Filter(
            'Registros de Formacin',
            Num_Empleado = Emp.Value 
        )
    )
);

// 4. LIMPIAMOS EL HISTORIAL DEJANDO SOLO LOS CURSOS QUE ESTÁN EN EL FILTRO SUPERIOR
ClearCollect(
    colRegistros,
    Filter(
        colRegistrosTemp,
        // Solo nos quedamos con los registros cuyo ID_Curso esté dentro de la lista de cursos filtrados
        Value(ID_Curso) in colCursosFiltrados.ID 
    )
);

ClearCollect(
    colMatrizFormacion,
    ForAll(
        colEmpleadosBase As Emp,
        {
            N_Empleado: Value(Emp.Value), 
            NombreCompleto: LookUp('Listado enviado a 04 Octubre', N_Empleado = Value(Emp.Value)).'Nombre Completo',
            TotalCursosPlan: CountRows(colCursosFiltrados),
            CursosCompletados: CountRows(Filter(colRegistros, Num_Empleado = Emp.Value))
        }
    )
);

UpdateContext({ctxCargando: false});
