// 2. OBTENEMOS LOS EMPLEADOS BASE
ClearCollect(
    colEmpleadosBase;
    Distinct(
        Filter(
            'Listado enviado a 04 Octubre'; 
            IsBlank(ComboBox_Equipo.Selected.Value) || Tipo_Empleo = ComboBox_Equipo.Selected.Value;
            IsBlank(ComboBox_N_Empleado.Selected.N_Empleado) || N_Empleado = Value(ComboBox_N_Empleado.Selected.N_Empleado)
        );
        N_Empleado
    )
);;

// 3. DESCARGAMOS TODO EL HISTORIAL DE FORMACIÓN DE ESOS EMPLEADOS
Clear(colRegistrosTemp);;
ForAll(
    colEmpleadosBase As Emp;
    Collect(
        colRegistrosTemp;
        Filter(
            'Registros de Formacin';
            Num_Empleado = Emp.Value 
        )
    )
);;

// 4. CRUZAMOS EL HISTORIAL POR **TÍTULO** (Para que valgan los de 2024 en 2026)
ClearCollect(
    colRegistros;
    Filter(
        colRegistrosTemp;
        LookUp('Cursos Formativos'; ID = Value(ID_Curso)).Title in colCursosFiltrados.Title 
    )
);;

// 5. CONSTRUIMOS LA MATRIZ DE PROGRESO
ClearCollect(
    colMatrizFormacion;
    ForAll(
        colEmpleadosBase As Emp;
        {
            N_Empleado: Value(Emp.Value); 
            NombreCompleto: LookUp('Listado enviado a 04 Octubre'; N_Empleado = Value(Emp.Value)).'Nombre Completo';
            TotalCursosPlan: CountRows(colCursosFiltrados);
            // Calculamos cuántos cursos requeridos tiene completados/aptos
            CursosCompletados: CountRows(
                Filter(
                    colCursosFiltrados;
                    With(
                        {
                            Reg: LookUp(colRegistros; Num_Empleado = Emp.Value && LookUp('Cursos Formativos'; ID = Value(ID_Curso)).Title = Title)
                        };
                        !IsBlank(Reg) && (Evaluacion = false || Reg.Apto = true || Reg.ILUO.Value in ["I"; "L"; "U"; "O"])
                    )
                )
            )
        }
    )
);;

UpdateContext({ctxCargando: false});;
Notify("Matriz organizada con éxito."; NotificationType.Success)

