With(
    {
        RegistroEncontrado: LookUp(
            colRegistros,
            Num_Empleado = Value(Label_N_Empleado_1.Text) && 
            ID_Curso = Value(ThisItem.ID)
        )
    },
    
    If(
        IsBlank(RegistroEncontrado),
        "NO REALIZADO",
        
        If(
            ThisItem.Area_Form = "MTTO", 
            Coalesce(RegistroEncontrado.ILUO.Value, "Falta letra"),
            
            If(
                ThisItem.Evaluacion = true,
                If(RegistroEncontrado.Apto = true, "REALIZADO", "NO REALIZADO"),
                
                If(
                    RegistroEncontrado.'Tiene datos adjuntos' = true, 
                    "REALIZADO", 
                    "NO REALIZADO"
                )
            )
        )
    )
